function summarize(report) {
  const lines = [`check: ${report.passed ? "passed" : "failed"}`];
  for (const stage of report.stages) {
    lines.push(`${stage.stage}: ${stage.status}`);
    for (const finding of stage.errors)
      lines.push(`  error ${finding.code}: ${finding.message}`);
    for (const finding of stage.warnings)
      lines.push(`  warning ${finding.code}: ${finding.message}`);
  }
  return lines.join(`
`);
}

